import {PNG} from 'pngjs';
import {observationFixture} from './agent-observation-fixture.mjs';
export function screenshotPng(width=640,height=480){const data=Buffer.alloc(width*height*4,255);for(let y=30;y<Math.min(70,height);y++)for(let x=20;x<Math.min(90,width);x++){const at=(y*width+x)*4;data[at]=17;data[at+1]=83;data[at+2]=151;}return PNG.sync.write({width,height,data});}
export function screenshotFixture(t){const base=observationFixture(t);let hook=null,png=screenshotPng();base.handler=async(method,params)=>{const custom=await hook?.(method,params);if(custom!==undefined)return custom;if(method==='Runtime.callFunctionOn'&&params.functionDeclaration.includes('screenshotMetadata'))return {result:{value:{ok:true,url:'https://fixture.test/',title:'Screenshot',truncated:false}}};if(method==='Page.captureScreenshot')return {data:png.toString('base64')};};const context=base.run.observationContext();return {base,context,capture:limits=>base.run.screenshot(context,limits),set hook(v){hook=v;},get png(){return png;},set png(v){png=v;}};}
